package com.cenedu.backend.ai.problem.render;
import com.cenedu.backend.domain.problem.authoring.diagram.*; import com.cenedu.backend.domain.problem.authoring.semantic.evaluation.SemanticResolvedValue; import java.util.*;
public final class PlaneGeometrySvgRenderer { public String render(PlaneGeometryDiagramSpecV1 s){return render(s,Map.of());} public String render(PlaneGeometryDiagramSpecV1 s,Map<String,SemanticResolvedValue> values){int p=s.viewport().padding();var b=new StringBuilder("<rect x=\"").append(p).append("\" y=\"").append(p).append("\" width=\"").append(s.viewport().width()-2*p).append("\" height=\"").append(s.viewport().height()-2*p).append("\" fill=\"none\" stroke=\"#000000\"/>");for(var point:s.points()){int x=p+20,y=p+20;try{x+=Integer.parseInt(values.get(point.xKey()).canonicalValue())*10;y+=Integer.parseInt(values.get(point.yKey()).canonicalValue())*10;}catch(Exception ignored){}b.append("<circle cx=\"").append(x).append("\" cy=\"").append(y).append("\" r=\"3\" fill=\"#000000\"/>");}for(var poly:s.polygons())if(poly.pointKeys().size()>=3)b.append("<polygon points=\"").append(p).append(",").append(p).append(" ").append(s.viewport().width()-p).append(",").append(p).append(" ").append(s.viewport().width()/2).append(",").append(s.viewport().height()-p).append("\" fill=\"none\" stroke=\"#000000\"/>");return b.toString();} }
